// qbAssess_main_idea.js — Main Idea
// 100 questions across three levels.
// Level 1 (difficulty 3): 3–4 sentence passages. Explicit main idea.
//   Question types: "What is this passage mainly about?" / "What is the best title?"
// Level 2 (difficulty 4): 5–6 sentence passages. Main idea requires synthesis across details.
//   Question types: "What is the main idea?" / "Which title fits best?" / "Which detail supports the main idea?"
// Level 3 (difficulty 5): 6–8 sentence passages. Main idea is implied or thematic.
//   Question types: "What is the main message?" / "Which statement best summarises?"

export const qbAssess_main_idea = [

  // ── LEVEL 1 — short passages, explicit main idea ──────────────────────────

  { id:"qa_mi_l1_001", grade:"1", skill:"main idea", skillId:"main_idea", difficulty:3, passage:"Dogs make great pets. They are loyal and friendly. Dogs love to play and go for walks with their owners.", question:"What is this passage mainly about?", choices:["Why dogs are good pets","How to train a dog","What dogs like to eat","Where dogs come from"], answer:"Why dogs are good pets", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l1_002", grade:"1", skill:"main idea", skillId:"main_idea", difficulty:3, passage:"Butterflies begin life as tiny eggs. They hatch into caterpillars and eat lots of leaves. Then they form a chrysalis before becoming butterflies.", question:"What is this passage mainly about?", choices:["How a butterfly grows and changes","What butterflies eat","Where butterflies lay eggs","Why caterpillars are green"], answer:"How a butterfly grows and changes", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l1_003", grade:"1", skill:"main idea", skillId:"main_idea", difficulty:3, passage:"The library is a great place to find books. You can borrow books for free. There are books about every topic you can think of.", question:"What would be the best title for this passage?", choices:["The Library — A Place for Books","How to Get a Library Card","Books That Are Hard to Find","Reading at Home"], answer:"The Library — A Place for Books", questionType:"multiple_choice", itemType:"main_idea", itemKey:"best_title" },
  { id:"qa_mi_l1_004", grade:"1", skill:"main idea", skillId:"main_idea", difficulty:3, passage:"Eating fruit and vegetables is good for your body. They give you vitamins and help you stay healthy. Doctors say you should eat five portions every day.", question:"What is this passage mainly about?", choices:["Why fruit and vegetables are important","How to cook vegetables","Which fruit tastes the best","Where vegetables grow"], answer:"Why fruit and vegetables are important", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l1_005", grade:"1", skill:"main idea", skillId:"main_idea", difficulty:3, passage:"Rain is very important for life on Earth. Plants need rain to grow. Animals and people need clean water to drink.", question:"What is the main idea of this passage?", choices:["Rain is essential for living things","Rain makes puddles","It is fun to play in the rain","Rainbows appear after rain"], answer:"Rain is essential for living things", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l1_006", grade:"1", skill:"main idea", skillId:"main_idea", difficulty:3, passage:"Exercise keeps your body strong and healthy. Running, swimming, and cycling are all types of exercise. Even walking each day is good for you.", question:"What is the best title for this passage?", choices:["Exercise Is Good for Your Health","How to Run Faster","Types of Swimming","The Best Sports to Play"], answer:"Exercise Is Good for Your Health", questionType:"multiple_choice", itemType:"main_idea", itemKey:"best_title" },
  { id:"qa_mi_l1_007", grade:"1", skill:"main idea", skillId:"main_idea", difficulty:3, passage:"Penguins are birds that cannot fly. They live in cold places near the South Pole. They use their wings as flippers to swim very well.", question:"What is this passage mainly about?", choices:["What penguins are like","How cold the South Pole is","Why birds cannot fly","How flippers help animals swim"], answer:"What penguins are like", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_topic" },
  { id:"qa_mi_l1_008", grade:"1", skill:"main idea", skillId:"main_idea", difficulty:3, passage:"Recycling helps protect the environment. When we recycle paper, plastic, and glass, less waste goes to landfill. Recycling also saves energy and natural resources.", question:"What is this passage mainly about?", choices:["Why recycling is important","How to sort your rubbish","What landfills look like","Which materials can be recycled"], answer:"Why recycling is important", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l1_009", grade:"1", skill:"main idea", skillId:"main_idea", difficulty:3, passage:"Seeds need water, sunlight, and soil to grow. Without these three things, a seed cannot sprout. Gardeners make sure their plants get all three.", question:"What would be the best title for this passage?", choices:["What Seeds Need to Grow","How to Plant a Garden","The History of Farming","Different Types of Seeds"], answer:"What Seeds Need to Grow", questionType:"multiple_choice", itemType:"main_idea", itemKey:"best_title" },
  { id:"qa_mi_l1_010", grade:"1", skill:"main idea", skillId:"main_idea", difficulty:3, passage:"Spiders spin webs to catch insects for food. The silk they make is very strong. Some spider webs can hold an insect many times heavier than the spider.", question:"What is this passage mainly about?", choices:["How spiders use webs to catch food","Why spider silk is colourful","Where spiders build their nests","How spiders care for their young"], answer:"How spiders use webs to catch food", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l1_011", grade:"1", skill:"main idea", skillId:"main_idea", difficulty:3, passage:"The sun provides heat and light for the Earth. Without the sun, plants could not grow. All life on Earth depends on the sun.", question:"What is the main idea?", choices:["Life on Earth depends on the sun","The sun is very hot","The sun rises in the morning","Plants need sunlight to make food"], answer:"Life on Earth depends on the sun", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l1_012", grade:"1", skill:"main idea", skillId:"main_idea", difficulty:3, passage:"Sleep is very important for children. During sleep, the body repairs itself and the brain sorts out memories. Children need at least nine hours of sleep each night.", question:"What is this passage mainly about?", choices:["Why sleep is important for children","What happens during dreaming","How to fall asleep quickly","Why children go to bed early"], answer:"Why sleep is important for children", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l1_013", grade:"1", skill:"main idea", skillId:"main_idea", difficulty:3, passage:"Whales are the largest animals on Earth. Blue whales can grow up to 30 metres long. They live in the ocean and breathe air through a blowhole.", question:"What is this passage mainly about?", choices:["Facts about whales","How blue whales find food","Why whales have blowholes","The size of the ocean"], answer:"Facts about whales", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_topic" },
  { id:"qa_mi_l1_014", grade:"1", skill:"main idea", skillId:"main_idea", difficulty:3, passage:"Volcanoes form where hot liquid rock called magma pushes up through the Earth's surface. When they erupt, they release lava, gas, and ash. Volcanoes can be found all over the world.", question:"What would be the best title?", choices:["What Volcanoes Are and How They Work","How Ash Falls from the Sky","Rocks Found Deep Underground","Famous Mountains Around the World"], answer:"What Volcanoes Are and How They Work", questionType:"multiple_choice", itemType:"main_idea", itemKey:"best_title" },
  { id:"qa_mi_l1_015", grade:"1", skill:"main idea", skillId:"main_idea", difficulty:3, passage:"Honey is made by bees. Worker bees collect nectar from flowers and bring it back to the hive. The nectar is turned into honey, which the bees use as food.", question:"What is this passage mainly about?", choices:["How bees make honey","Why flowers have nectar","How bee hives are built","What bees eat in winter"], answer:"How bees make honey", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l1_016", grade:"1", skill:"main idea", skillId:"main_idea", difficulty:3, passage:"Forests are home to millions of animals, birds, and insects. They also help clean the air we breathe. Forests around the world are in danger from cutting and burning.", question:"What is this passage mainly about?", choices:["Why forests are important and under threat","How animals find shelter in forests","What types of trees grow in forests","Why birds build nests in trees"], answer:"Why forests are important and under threat", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l1_017", grade:"1", skill:"main idea", skillId:"main_idea", difficulty:3, passage:"Maps help us find our way from one place to another. They show roads, rivers, and towns. Sailors and explorers used maps long before GPS was invented.", question:"What is the main idea?", choices:["Maps help people navigate and find their way","How rivers are shown on maps","The history of GPS technology","Why explorers travelled to new places"], answer:"Maps help people navigate and find their way", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l1_018", grade:"1", skill:"main idea", skillId:"main_idea", difficulty:3, passage:"Music can change how you feel. Slow, quiet music can calm you down. Fast, loud music can make you feel excited and energetic.", question:"What is the best title?", choices:["How Music Affects Our Feelings","How to Play the Piano","Famous Pieces of Music","Why Music Is Taught in Schools"], answer:"How Music Affects Our Feelings", questionType:"multiple_choice", itemType:"main_idea", itemKey:"best_title" },
  { id:"qa_mi_l1_019", grade:"1", skill:"main idea", skillId:"main_idea", difficulty:3, passage:"Clean water is something many people in the world do not have. Without it, people can become very ill. Charities work to bring clean water to communities that need it.", question:"What is this passage mainly about?", choices:["The importance of clean water for people","How charities raise money","What happens when rivers flood","How to purify water at home"], answer:"The importance of clean water for people", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l1_020", grade:"1", skill:"main idea", skillId:"main_idea", difficulty:3, passage:"Reading helps your brain in many ways. It grows your vocabulary and improves your spelling. Reading stories also helps you understand other people's feelings.", question:"What is this passage mainly about?", choices:["The benefits of reading","How to find good books","Why spelling is difficult","Stories from around the world"], answer:"The benefits of reading", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l1_021", grade:"1", skill:"main idea", skillId:"main_idea", difficulty:3, passage:"The Moon does not produce its own light. It reflects the light from the Sun. That is why we can see it in the night sky.", question:"What is this passage mainly about?", choices:["Where the Moon's light comes from","How far the Moon is from Earth","Why the Moon changes shape","The surface of the Moon"], answer:"Where the Moon's light comes from", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_topic" },
  { id:"qa_mi_l1_022", grade:"1", skill:"main idea", skillId:"main_idea", difficulty:3, passage:"Teeth need to be looked after carefully. Brushing twice a day removes plaque. Eating too much sugar can cause tooth decay.", question:"What would be the best title?", choices:["How to Keep Your Teeth Healthy","Foods That Are Bad for You","How Dentists Fix Teeth","What Plaque Is Made Of"], answer:"How to Keep Your Teeth Healthy", questionType:"multiple_choice", itemType:"main_idea", itemKey:"best_title" },
  { id:"qa_mi_l1_023", grade:"1", skill:"main idea", skillId:"main_idea", difficulty:3, passage:"The Amazon River is one of the longest rivers in the world. It flows through South America and into the Atlantic Ocean. Many rare animals live in and around its waters.", question:"What is this passage mainly about?", choices:["Facts about the Amazon River","How rivers reach the sea","Animals that live in rivers","South American geography"], answer:"Facts about the Amazon River", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_topic" },
  { id:"qa_mi_l1_024", grade:"1", skill:"main idea", skillId:"main_idea", difficulty:3, passage:"Washing your hands is one of the best ways to stop germs spreading. You should wash them before eating and after using the toilet. Soap and warm water kill most germs.", question:"What is the main idea?", choices:["Washing hands prevents the spread of germs","Why soap is better than water alone","How germs get into food","What to do when you are ill"], answer:"Washing hands prevents the spread of germs", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l1_025", grade:"1", skill:"main idea", skillId:"main_idea", difficulty:3, passage:"Ice caps at the North and South Poles are melting. This is causing sea levels to rise around the world. Scientists say that climate change is making the problem worse.", question:"What is this passage mainly about?", choices:["How climate change is affecting the polar ice caps","Why scientists study the poles","What animals live at the South Pole","How glaciers form over thousands of years"], answer:"How climate change is affecting the polar ice caps", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l1_026", grade:"1", skill:"main idea", skillId:"main_idea", difficulty:3, passage:"Frogs are amphibians. They can live both in water and on land. Frogs lay their eggs in water, and the young begin life as tadpoles.", question:"What is this passage mainly about?", choices:["What frogs are and how they live","Why tadpoles live in water","Where amphibians are found","How frog eggs hatch"], answer:"What frogs are and how they live", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_topic" },
  { id:"qa_mi_l1_027", grade:"1", skill:"main idea", skillId:"main_idea", difficulty:3, passage:"The Great Wall of China was built to protect China from invaders. It stretches thousands of kilometres across mountains and plains. Millions of workers built it over hundreds of years.", question:"What would be the best title?", choices:["The Great Wall of China — Its Purpose and History","China's Famous Landmarks","How Mountains Protect Countries","Ancient Building Methods"], answer:"The Great Wall of China — Its Purpose and History", questionType:"multiple_choice", itemType:"main_idea", itemKey:"best_title" },
  { id:"qa_mi_l1_028", grade:"1", skill:"main idea", skillId:"main_idea", difficulty:3, passage:"Air is all around us even though we cannot see it. We breathe it in to stay alive. Air is made up of several gases, mostly nitrogen and oxygen.", question:"What is this passage mainly about?", choices:["What air is and why it matters","How oxygen is made","Why the sky is blue","What happens when air moves"], answer:"What air is and why it matters", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l1_029", grade:"1", skill:"main idea", skillId:"main_idea", difficulty:3, passage:"Bats are the only mammals that can fly. Most bats are active at night and sleep during the day. They use sound waves to find their way in the dark.", question:"What is the main idea?", choices:["Bats are unusual mammals with special abilities","Why animals sleep during the day","How sound travels through the air","The difference between mammals and birds"], answer:"Bats are unusual mammals with special abilities", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l1_030", grade:"1", skill:"main idea", skillId:"main_idea", difficulty:3, passage:"Gravity is the force that keeps us on the ground. It pulls objects towards the centre of the Earth. Without gravity, everything would float away into space.", question:"What is this passage mainly about?", choices:["What gravity is and what it does","Why things fall when you drop them","How astronauts float in space","The size and weight of the Earth"], answer:"What gravity is and what it does", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l1_031", grade:"1", skill:"main idea", skillId:"main_idea", difficulty:3, passage:"The human heart pumps blood around the body. It beats around seventy times per minute. Without the heart, the body cannot deliver oxygen to where it is needed.", question:"What is this passage mainly about?", choices:["The role of the heart in the body","How fast blood travels","Why oxygen is important","What happens when the heart beats fast"], answer:"The role of the heart in the body", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l1_032", grade:"1", skill:"main idea", skillId:"main_idea", difficulty:3, passage:"Camels can survive in the desert for days without water. Their humps store fat for energy. Wide, flat feet stop them from sinking in the sand.", question:"What is the best title?", choices:["How Camels Are Built for the Desert","Animals That Live Without Water","The Hot Deserts of the World","What Camels Eat and Drink"], answer:"How Camels Are Built for the Desert", questionType:"multiple_choice", itemType:"main_idea", itemKey:"best_title" },
  { id:"qa_mi_l1_033", grade:"1", skill:"main idea", skillId:"main_idea", difficulty:3, passage:"Plastic takes hundreds of years to break down. It ends up in oceans and harms sea animals. Using less plastic is one way to help protect the ocean.", question:"What is this passage mainly about?", choices:["The harm plastic causes to the environment","How long different materials last","Why oceans are important","The best ways to recycle at home"], answer:"The harm plastic causes to the environment", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l1_034", grade:"1", skill:"main idea", skillId:"main_idea", difficulty:3, passage:"Dinosaurs lived millions of years ago. They came in many shapes and sizes, from tiny to enormous. They died out after a massive asteroid hit the Earth.", question:"What is this passage mainly about?", choices:["An overview of the dinosaurs and their extinction","Why asteroids are dangerous","Which dinosaur was the largest","How fossils of dinosaurs are found"], answer:"An overview of the dinosaurs and their extinction", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_topic" },
  { id:"qa_mi_l1_035", grade:"1", skill:"main idea", skillId:"main_idea", difficulty:3, passage:"Kindness can have a big effect on people. A simple smile or a kind word can brighten someone's day. Small acts of kindness can spread and inspire others.", question:"What is the main idea?", choices:["Kindness matters and can make a real difference","How to make new friends","Why smiling is good for your health","When to help people you don't know"], answer:"Kindness matters and can make a real difference", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l1_036", grade:"1", skill:"main idea", skillId:"main_idea", difficulty:3, passage:"Earthquakes happen when plates of rock beneath the Earth move and rub against each other. They can cause buildings to shake and fall. Areas near plate edges get more earthquakes.", question:"What is this passage mainly about?", choices:["What earthquakes are and why they happen","How to survive an earthquake","Why buildings fall down","The plates that make up the ocean floor"], answer:"What earthquakes are and why they happen", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l1_037", grade:"1", skill:"main idea", skillId:"main_idea", difficulty:3, passage:"A healthy breakfast gives you energy for the morning. It helps you concentrate at school. Children who eat breakfast tend to do better in lessons.", question:"What would be the best title?", choices:["Why Breakfast Is Important for Children","What to Eat for Dinner","How the Body Uses Energy","Foods That Give You a Headache"], answer:"Why Breakfast Is Important for Children", questionType:"multiple_choice", itemType:"main_idea", itemKey:"best_title" },
  { id:"qa_mi_l1_038", grade:"1", skill:"main idea", skillId:"main_idea", difficulty:3, passage:"The fire station is an important part of the community. Firefighters respond to emergencies quickly. They also teach people how to prevent fires and stay safe.", question:"What is the main idea?", choices:["Firefighters serve and protect the community","How fire engines are built","The history of fire stations","What to do if you smell smoke"], answer:"Firefighters serve and protect the community", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l1_039", grade:"1", skill:"main idea", skillId:"main_idea", difficulty:3, passage:"Migration is when animals travel long distances to find food or warmer weather. Birds such as swallows fly from Europe to Africa each winter. In spring, they return north again.", question:"What is this passage mainly about?", choices:["Animal migration and why it happens","How fast birds can fly","The distance between Europe and Africa","Why birds build nests in spring"], answer:"Animal migration and why it happens", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l1_040", grade:"1", skill:"main idea", skillId:"main_idea", difficulty:3, passage:"Stars are huge balls of burning gas in space. Our Sun is a star. Stars look small because they are so far away from Earth.", question:"What is this passage mainly about?", choices:["What stars are","How the Sun keeps us warm","Why the sky is dark at night","How scientists study space"], answer:"What stars are", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_topic" },

  // ── LEVEL 2 — 5–6 sentence passages, synthesis required ───────────────────

  { id:"qa_mi_l2_001", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:4, passage:"Wolves live and hunt in family groups called packs. Each pack has a leader, called the alpha wolf. Pack members help each other find food and raise pups. They communicate through howls that can be heard from miles away. Working together helps wolves survive in the wild.", question:"What is the main idea of this passage?", choices:["Wolves are social animals that work together to survive","Wolves make loud howls to communicate","The alpha wolf leads the pack on hunts","Wolf pups are raised by the whole pack"], answer:"Wolves are social animals that work together to survive", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l2_002", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:4, passage:"The printing press was invented in the 1400s. Before it existed, books had to be written by hand, which took months. The printing press could produce hundreds of books quickly. This meant more people could afford to own books. As a result, knowledge spread faster than ever before.", question:"What is the main idea?", choices:["The printing press changed how knowledge was shared","Books used to be very expensive","Printing presses could produce hundreds of copies","Writing books by hand took a very long time"], answer:"The printing press changed how knowledge was shared", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l2_003", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:4, passage:"Coral reefs are sometimes called the rainforests of the sea. They cover less than one percent of the ocean floor but are home to twenty-five percent of all marine species. Fish, turtles, and thousands of other creatures depend on them for shelter and food. Coral reefs also protect coastlines from storm damage. Despite their importance, many reefs are dying because of warming oceans.", question:"What is the best title for this passage?", choices:["Coral Reefs — Vital, Diverse, and Under Threat","The Animals That Live in the Ocean","Why the Ocean Is Warming","How Coastlines Are Formed"], answer:"Coral Reefs — Vital, Diverse, and Under Threat", questionType:"multiple_choice", itemType:"main_idea", itemKey:"best_title" },
  { id:"qa_mi_l2_004", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:4, passage:"Thomas Edison is known as one of the greatest inventors in history. He invented the light bulb, the phonograph, and many other devices. He often said that invention was one percent inspiration and ninety-nine percent hard work. He failed thousands of times before succeeding. His work changed daily life for people all over the world.", question:"What is the main idea?", choices:["Edison's determination and hard work made him a great inventor","Edison invented the light bulb after many failures","Edison believed in working hard to succeed","Edison invented many devices used in daily life"], answer:"Edison's determination and hard work made him a great inventor", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l2_005", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:4, passage:"Astronauts on the International Space Station live in a unique environment. Without gravity, they float everywhere and must strap themselves in to sleep. They exercise for two hours every day to stop their muscles from weakening. Simple tasks like washing and eating require special equipment. Despite the challenges, astronauts describe life in space as an amazing experience.", question:"What is this passage mainly about?", choices:["What daily life is like for astronauts in space","How gravity affects the human body","Why astronauts must exercise in space","The equipment needed on a space station"], answer:"What daily life is like for astronauts in space", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_topic" },
  { id:"qa_mi_l2_006", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:4, passage:"Every spring, thousands of salmon swim from the ocean up rivers to the streams where they were born. They swim against strong currents and jump over waterfalls. Many predators, including bears and eagles, wait along the way. Most salmon die shortly after laying their eggs. But their bodies provide food for the forests and rivers around them.", question:"What is the main idea?", choices:["The remarkable and costly journey salmon make to reproduce","Why bears and eagles feed on salmon","How salmon find the stream where they were born","The role of salmon in forest ecosystems"], answer:"The remarkable and costly journey salmon make to reproduce", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l2_007", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:4, passage:"Ancient Egyptians developed one of the world's earliest writing systems, called hieroglyphics. Each symbol represented a sound or a word. Only specially trained scribes could read and write it. Hieroglyphics were carved into temple walls and written on scrolls. This writing system helped Egyptians record history, laws, and religious beliefs.", question:"What is the best title?", choices:["Hieroglyphics — Egypt's Ancient Writing System","How to Read Ancient Symbols","The History of Ancient Egypt","Why Scribes Were Important in the Ancient World"], answer:"Hieroglyphics — Egypt's Ancient Writing System", questionType:"multiple_choice", itemType:"main_idea", itemKey:"best_title" },
  { id:"qa_mi_l2_008", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:4, passage:"Community gardens bring people together from all backgrounds. Neighbours who have never spoken can find themselves working side by side growing vegetables and flowers. Children learn where food comes from by getting their hands in the soil. Older residents share knowledge they have built up over years. A single patch of land can become the heart of a neighbourhood.", question:"What is the main idea?", choices:["Community gardens connect and strengthen neighbourhoods","Vegetables grow well in shared spaces","Children benefit from learning about growing food","Gardens are good for mental health"], answer:"Community gardens connect and strengthen neighbourhoods", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l2_009", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:4, passage:"Sign language is a complete language that uses hand movements, facial expressions, and body posture to communicate. Different countries have their own sign languages. It is not just a system of gestures but a rich, expressive language with its own grammar. Deaf people use it as their first language. Learning basic sign language can help hearing people communicate with the Deaf community.", question:"What is this passage mainly about?", choices:["Sign language is a full and important language","How to learn basic sign language","Why deaf people cannot hear","The differences between sign languages around the world"], answer:"Sign language is a full and important language", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l2_010", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:4, passage:"The first Olympic Games were held in ancient Greece around 776 BC. They were a religious festival held in honour of the god Zeus. Athletes from different Greek cities came to compete. Women were not allowed to compete or even watch. The modern Olympics, restarted in 1896, are now open to athletes from every country in the world.", question:"What is the main idea?", choices:["The Olympic Games have a long history and have changed over time","The ancient Greeks held games for Zeus","Women were excluded from the original Olympics","The modern Olympics began in 1896"], answer:"The Olympic Games have a long history and have changed over time", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l2_011", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:4, passage:"Screen time has increased significantly for children in recent years. Many children spend several hours a day watching videos or playing games. Some research suggests this can reduce time spent on physical activity. Others argue that technology can also be educational and social. Most experts recommend a balance between screen time and other activities.", question:"What is the main idea?", choices:["Screen time is a growing issue with complex effects on children","Children watch too much television","Technology is always harmful for young people","Experts have found that all screens damage children's health"], answer:"Screen time is a growing issue with complex effects on children", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l2_012", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:4, passage:"Florence Nightingale transformed the way hospitals were run. During the Crimean War, she arrived at a military hospital with terrible conditions. She insisted on cleanliness, fresh air, and proper nutrition for patients. The death rate fell dramatically under her care. Her work established nursing as a respected profession and changed medical care forever.", question:"What is the best title?", choices:["Florence Nightingale — How She Changed Nursing and Medicine","Hospitals During the Crimean War","The Importance of Hygiene in Medicine","Famous Women in History"], answer:"Florence Nightingale — How She Changed Nursing and Medicine", questionType:"multiple_choice", itemType:"main_idea", itemKey:"best_title" },
  { id:"qa_mi_l2_013", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:4, passage:"The Sahara Desert is the world's largest hot desert, covering most of North Africa. Despite being extremely dry, it is home to many animals, including fennec foxes, scorpions, and camels. Some parts of the Sahara receive no rain for years. Yet ancient cave paintings show that the Sahara was once green and full of rivers. Scientists believe it will become wetter again in thousands of years.", question:"What is the main idea?", choices:["The Sahara is a vast and surprising desert with a changing history","The Sahara Desert is in North Africa","Animals have adapted to survive in the Sahara","Ancient people once lived in the Sahara"], answer:"The Sahara is a vast and surprising desert with a changing history", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l2_014", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:4, passage:"Music lessons offer children more than just musical skills. Practising an instrument builds patience and discipline. Learning to read music strengthens mathematical thinking. Playing in an ensemble teaches children to listen and work with others. Even children who do not continue with music later in life benefit from these skills.", question:"What is the main idea?", choices:["Music lessons develop important skills beyond music","Playing an instrument requires patience and practice","Children who play in ensembles learn to cooperate","Music education improves maths skills in young children"], answer:"Music lessons develop important skills beyond music", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l2_015", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:4, passage:"Antibiotics are medicines that kill bacteria. Before they were discovered, infections that are now easy to treat could be deadly. Alexander Fleming discovered the first antibiotic, penicillin, in 1928. Since then, antibiotics have saved millions of lives. However, taking antibiotics too often can make bacteria resistant to them, which is a growing problem.", question:"What is this passage mainly about?", choices:["The importance and risks of antibiotics","How Alexander Fleming discovered penicillin","Why bacteria become resistant to medicine","Infections that were once deadly"], answer:"The importance and risks of antibiotics", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_topic" },
  { id:"qa_mi_l2_016", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:4, passage:"Urban farming is the practice of growing food in cities. People grow vegetables on rooftops, in community plots, and even on balconies. It can reduce the distance food travels from farm to plate. City farming also gives people a connection with nature in an urban environment. As cities grow, urban farming is seen as one solution to feeding more people sustainably.", question:"What is the main idea?", choices:["Urban farming is a growing and valuable way of producing food in cities","People can grow vegetables on their balconies","City farming reduces how far food travels","Urban farming will feed the world's growing cities"], answer:"Urban farming is a growing and valuable way of producing food in cities", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l2_017", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:4, passage:"The invention of the wheel is considered one of the most important in human history. Before it, people carried goods by hand or on the backs of animals. The wheel allowed carts to be built, making it far easier to transport heavy loads over long distances. Later, wheels were used in machines and engines. Almost every vehicle used today depends on the wheel.", question:"What is the best title?", choices:["The Wheel — One of History's Greatest Inventions","How Carts Changed Ancient Trade","Why Machines Need Rotating Parts","The History of Transport"], answer:"The Wheel — One of History's Greatest Inventions", questionType:"multiple_choice", itemType:"main_idea", itemKey:"best_title" },
  { id:"qa_mi_l2_018", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:4, passage:"Tortoises are among the longest-living animals on Earth. Some have been recorded living for over two hundred years. Their slow metabolism and hard shell help protect them from predators. They spend much of their time basking in the sun to warm up. Scientists study tortoises to understand more about ageing and longevity.", question:"What is the main idea?", choices:["Tortoises are extraordinary animals known for their remarkable lifespan","Tortoise shells protect them from predators","Scientists study tortoises to learn about ageing","Tortoises need sunlight to regulate their body temperature"], answer:"Tortoises are extraordinary animals known for their remarkable lifespan", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l2_019", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:4, passage:"Friendship plays a major role in children's wellbeing. Having even one close friend makes children feel happier and less anxious. Friends help each other through difficult times and celebrate good ones. Children with strong friendships tend to do better socially as adults. Schools that support children in building friendships help them in many ways beyond academic learning.", question:"What is the main idea?", choices:["Friendship is important for children's happiness and development","Having friends helps children do better at school","Adults who had childhood friends are more successful","Schools should do more to help children make friends"], answer:"Friendship is important for children's happiness and development", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l2_020", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:4, passage:"Deserts cover about one-third of the Earth's land surface. They can be hot or cold — Antarctica is actually the world's largest cold desert. What makes a desert is not heat but dryness — any region that receives less than 250 millimetres of rain per year is a desert. Despite being dry, deserts support a surprising range of life. Cacti, insects, reptiles, and mammals have all adapted to survive there.", question:"What is this passage mainly about?", choices:["What deserts really are and the surprising life they support","Why Antarctica is considered a desert","How plants survive in hot, dry conditions","The percentage of land covered by deserts"], answer:"What deserts really are and the surprising life they support", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l2_021", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:4, passage:"Solar panels convert sunlight into electricity. They are now found on rooftops, in fields, and even on spacecraft. The cost of solar panels has dropped significantly in recent years, making them more accessible. They produce no pollution during use, making them one of the cleanest energy sources available. Many countries are investing heavily in solar power as part of their plans to tackle climate change.", question:"What is the main idea?", choices:["Solar panels are a clean, growing energy source becoming more affordable","Solar panels are found in many different locations","Solar power does not produce any pollution","Governments are spending money on solar energy"], answer:"Solar panels are a clean, growing energy source becoming more affordable", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l2_022", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:4, passage:"Public libraries face challenges in the modern age. As people read more on screens, fewer visitors come through the doors. Many councils have reduced funding for libraries, leading to closures. Yet research shows that libraries are still valued deeply by their communities. They provide not just books but access to the internet, warm spaces, and local events for all ages.", question:"What is the main idea?", choices:["Libraries remain important community spaces despite modern pressures","People now prefer to read on screens","Local councils are closing too many libraries","Libraries provide more services than just lending books"], answer:"Libraries remain important community spaces despite modern pressures", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l2_023", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:4, passage:"Elephants show remarkable signs of intelligence and emotion. They mourn their dead and have been observed returning to the bones of family members for years after a death. They cooperate to solve problems and can use tools. Young elephants are playful and learn from their elders. Some research suggests they can even recognise themselves in a mirror, a rare ability in the animal kingdom.", question:"What is the best title?", choices:["Elephants — Intelligent, Emotional, and Highly Social Animals","Why Elephants Return to Bones","Animal Intelligence in the Wild","How Elephants Learn from Each Other"], answer:"Elephants — Intelligent, Emotional, and Highly Social Animals", questionType:"multiple_choice", itemType:"main_idea", itemKey:"best_title" },
  { id:"qa_mi_l2_024", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:4, passage:"Volunteering benefits both the volunteers and those they help. People who volunteer report feeling happier and more connected to their community. They gain skills and experience that can help in later careers. The organisations they support could not function without unpaid help. Across the country, millions of volunteer hours keep charities, sports clubs, and community groups running.", question:"What is the main idea?", choices:["Volunteering benefits individuals and communities in many ways","Charities could not run without volunteers","Volunteering makes people happier and more connected","Volunteers gain skills useful in future careers"], answer:"Volunteering benefits individuals and communities in many ways", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l2_025", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:4, passage:"The human brain is remarkably adaptable, especially in childhood. This is known as neuroplasticity. When children learn new skills, the brain forms new connections. Challenging activities — such as learning an instrument, a language, or a sport — strengthen these connections. Even recovering from brain injury is often more successful in children than in adults, thanks to the brain's ability to rewire itself.", question:"What is this passage mainly about?", choices:["The brain's remarkable ability to change and adapt, especially in childhood","Why children learn languages faster than adults","How the brain recovers from injury","What neuroplasticity means"], answer:"The brain's remarkable ability to change and adapt, especially in childhood", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_topic" },
  { id:"qa_mi_l2_026", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:4, passage:"Many people in the modern world struggle to disconnect from technology. Phones, emails, and social media create a constant stream of information and demands. Some research links heavy phone use to increased anxiety and poor sleep. A growing movement encourages 'digital detox' — periods without devices. Experts suggest that time away from screens can improve wellbeing and relationships.", question:"What is the main idea?", choices:["Constant technology use has downsides and some suggest switching off more","Social media causes anxiety and poor sleep","Experts recommend spending no time on phones","A growing number of people are quitting social media"], answer:"Constant technology use has downsides and some suggest switching off more", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l2_027", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:4, passage:"Honeybees are vital to agriculture. As they move from flower to flower collecting nectar, they transfer pollen between plants. This process, called pollination, is essential for many crops to produce fruit and seeds. Without honeybees, many of the foods we eat would be in short supply. Scientists are concerned that bee populations are declining due to pesticides, habitat loss, and disease.", question:"What is the main idea?", choices:["Honeybees are essential to food production and face serious threats","Bees collect nectar and pollen from flowers","Pollination is the process by which plants reproduce","Bee populations are being harmed by pesticides and habitat loss"], answer:"Honeybees are essential to food production and face serious threats", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l2_028", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:4, passage:"Clean energy from renewable sources is growing worldwide. Wind turbines now dot hillsides and coastlines across many countries. Solar farms are being built in deserts and fields. Hydroelectric dams produce electricity from moving water. Together, these sources already provide a significant portion of the world's electricity. Experts say renewables must grow much further to meet climate targets.", question:"What is the best title?", choices:["Renewable Energy — A Growing Answer to the Climate Crisis","How Wind Turbines Generate Electricity","Why Solar Farms Are Built in Deserts","The Future of Hydroelectric Power"], answer:"Renewable Energy — A Growing Answer to the Climate Crisis", questionType:"multiple_choice", itemType:"main_idea", itemKey:"best_title" },
  { id:"qa_mi_l2_029", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:4, passage:"The story of the Titanic has fascinated people for over a century. The ship was considered unsinkable when it set sail in 1912. It struck an iceberg and sank on its first voyage, killing over 1,500 people. The disaster led to new rules about lifeboats and iceberg patrols at sea. Today, the wreck lies on the ocean floor and continues to be studied by explorers.", question:"What is the main idea?", choices:["The Titanic's tragic sinking had a lasting impact on maritime safety","The Titanic was believed to be unsinkable","More than 1,500 people died when the Titanic sank","Explorers continue to study the Titanic's wreck today"], answer:"The Titanic's tragic sinking had a lasting impact on maritime safety", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l2_030", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:4, passage:"Space exploration has brought many benefits to life on Earth. Technologies developed for space missions, such as memory foam and GPS, are now used every day. Space exploration has inspired generations of scientists and engineers. It has also helped us understand our own planet better. Despite the enormous cost, many argue that the benefits make it worthwhile.", question:"What is this passage mainly about?", choices:["Space exploration has produced benefits that go beyond space itself","GPS was developed for space missions","Space exploration is very expensive to fund","Scientists and engineers are inspired by space travel"], answer:"Space exploration has produced benefits that go beyond space itself", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_topic" },
  { id:"qa_mi_l2_031", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:4, passage:"Many ancient civilisations built their cities near rivers. The Nile in Egypt, the Tigris and Euphrates in Mesopotamia, and the Indus in South Asia all supported great early societies. Rivers provided fresh water, fertile soil for farming, and routes for trade. Without reliable water, these civilisations could not have fed their populations or grown their economies.", question:"What is the main idea?", choices:["Rivers were essential to the growth of ancient civilisations","Ancient Egypt depended on the Nile River","Fertile river soil was used to grow food","Trade routes followed the paths of rivers"], answer:"Rivers were essential to the growth of ancient civilisations", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l2_032", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:4, passage:"Languages are disappearing at an alarming rate. Around half of the world's seven thousand languages are expected to vanish within a century. When a language dies, unique ways of describing the world are lost forever. Many indigenous languages contain knowledge about local plants, animals, and environments. Efforts are underway to record and revive endangered languages before they disappear.", question:"What is the main idea?", choices:["The loss of languages means the loss of irreplaceable knowledge and culture","Half of all languages will be gone in a hundred years","Indigenous languages contain knowledge about the natural world","Linguists are working to save endangered languages"], answer:"The loss of languages means the loss of irreplaceable knowledge and culture", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l2_033", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:4, passage:"Play is not just fun for children — it is essential to their development. Through play, children learn to use their imagination and solve problems. Physical play develops strength and coordination. Playing with others teaches children how to share, take turns, and manage emotions. Even unstructured, free play with no adult direction has been shown to develop independence and creativity.", question:"What is the best title?", choices:["Why Play Is Essential to Children's Development","How Children Use Their Imagination","The Difference Between Structured and Free Play","Why Children Need Physical Activity"], answer:"Why Play Is Essential to Children's Development", questionType:"multiple_choice", itemType:"main_idea", itemKey:"best_title" },
  { id:"qa_mi_l2_034", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:4, passage:"The ocean covers about seventy percent of the Earth's surface. It regulates the climate by absorbing heat and carbon dioxide from the atmosphere. It produces more than half of the oxygen we breathe. Billions of people rely on fish from the ocean as their main source of protein. Yet the ocean is under threat from pollution, overfishing, and rising temperatures.", question:"What is the main idea?", choices:["The ocean is vital to life on Earth but faces serious threats","The ocean covers most of the Earth's surface","Oceans produce more than half of our oxygen","Climate change is raising ocean temperatures"], answer:"The ocean is vital to life on Earth but faces serious threats", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l2_035", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:4, passage:"Emotional intelligence is the ability to understand and manage your own feelings and to recognise the feelings of others. Research suggests it can be just as important as academic intelligence in predicting success in life. People with high emotional intelligence tend to have better relationships and handle stress more effectively. Schools around the world are beginning to teach emotional skills alongside traditional subjects. Some experts argue it should be central to education.", question:"What is this passage mainly about?", choices:["Emotional intelligence is an important and undervalued skill","Emotional intelligence predicts success better than academic ability","Schools are starting to teach children how to manage emotions","Research shows that happy people are more successful"], answer:"Emotional intelligence is an important and undervalued skill", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_topic" },
  { id:"qa_mi_l2_036", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:4, passage:"The Great Fire of London in 1666 destroyed most of the medieval city. It started in a bakery on Pudding Lane and spread quickly through wooden buildings. Although around thirteen thousand houses were destroyed, surprisingly few people died. The fire led to the rebuilding of the city in brick and stone. New safety rules and the first fire insurance companies came about as a direct result.", question:"What is the main idea?", choices:["The Great Fire of London destroyed the city but led to important improvements","The fire started in a bakery on Pudding Lane","Few people died in the Great Fire of London","The fire led to the creation of fire insurance"], answer:"The Great Fire of London destroyed the city but led to important improvements", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l2_037", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:4, passage:"Robots are increasingly doing jobs that were once only done by humans. In factories, robots assemble cars and package food faster and more accurately than people. Some hospitals use robots to carry out precise surgical operations. Artificial intelligence allows robots to learn and improve over time. While this creates concern about jobs, it also frees humans to do tasks that require creativity and human judgement.", question:"What is the main idea?", choices:["Robots are taking on more human roles, creating both opportunities and concerns","Factory robots can work faster and more accurately than humans","Artificial intelligence allows robots to learn new tasks","Robots in hospitals perform very precise surgeries"], answer:"Robots are taking on more human roles, creating both opportunities and concerns", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l2_038", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:4, passage:"Microplastics are tiny pieces of plastic less than five millimetres in size. They come from larger pieces of plastic that have broken down, or from products like clothing fibres and cosmetics. Scientists have found microplastics in the ocean, in tap water, in the air, and even in human blood. The long-term effects on health are not yet fully understood. Research into microplastics is now a fast-growing area of science.", question:"What is this passage mainly about?", choices:["Microplastics are a widespread and poorly understood environmental problem","Microplastics are found in human blood","Microplastics come from broken-down plastic and clothing fibres","Scientists are studying the health effects of microplastics"], answer:"Microplastics are a widespread and poorly understood environmental problem", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_topic" },
  { id:"qa_mi_l2_039", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:4, passage:"The discovery of penicillin in 1928 changed medicine forever. Alexander Fleming noticed that a mould was killing bacteria in his laboratory. Further research turned this observation into the first antibiotic. Before penicillin, simple infections could be fatal. After its widespread use, millions of lives were saved that would previously have been lost to treatable conditions.", question:"What is the best title?", choices:["Penicillin — A Discovery That Changed Medicine","Alexander Fleming's Life in the Laboratory","How Antibiotics Kill Bacteria","The History of Medicine in the Twentieth Century"], answer:"Penicillin — A Discovery That Changed Medicine", questionType:"multiple_choice", itemType:"main_idea", itemKey:"best_title" },
  { id:"qa_mi_l2_040", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:4, passage:"Wetlands such as marshes and swamps are among the most productive ecosystems on Earth. They act as natural water filters, removing pollutants before they reach rivers and seas. Wetlands slow down flooding by absorbing heavy rain. They provide habitats for a huge range of birds, fish, and insects. Despite their value, many wetlands have been drained for farming and development.", question:"What is the main idea?", choices:["Wetlands are valuable ecosystems that are being lost","Wetlands filter pollutants from water","Wetlands help prevent flooding by absorbing rainfall","Marshes and swamps support a rich variety of wildlife"], answer:"Wetlands are valuable ecosystems that are being lost", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },

  // ── LEVEL 3 — longer passages, implied or thematic main idea ─────────────

  { id:"qa_mi_l3_001", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:5, passage:"Amara had been working on her science project for three weeks. She had tested four different types of soil, read seven books, and stayed up past her bedtime twice. When her partner wanted to use simpler methods to save time, Amara kept pushing for the most thorough approach. Her teacher noted that she always asked why, never just what. On presentation day, Amara's group had more data than any other. She didn't think of herself as particularly clever — just very curious.", question:"Which statement best summarises what this passage is about?", choices:["Curiosity and determination drive Amara's approach to learning","Amara works harder than everyone else in her class","Science projects should use as much data as possible","Staying up late is sometimes worth it to finish your work"], answer:"Curiosity and determination drive Amara's approach to learning", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l3_002", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:5, passage:"The pond in the school garden was quiet all winter. In spring, Amir's class visited it every Friday. First they saw frogspawn, like little dots in jelly. Then came tadpoles, then tiny frogs with new legs. Nobody told the pond to change. It followed its own slow plan. By summer, the class had learned that if you keep watching the same small place, it will show you something new.", question:"What is the main message of this passage?", choices:["Watching nature closely over time reveals wonderful changes","Frogspawn looks like little dots in jelly","Ponds are quiet in the winter","Amir's class visited the pond every Friday"], answer:"Watching nature closely over time reveals wonderful changes", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l3_003", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:5, passage:"Research on memory consistently shows that rest and sleep are more important for learning than many people realise. Students who review their notes and then sleep perform better in tests the next day than those who stay up all night studying. The brain consolidates memories during sleep, strengthening connections formed during the day. Spacing out study over several days is more effective than cramming. Yet most schools still schedule exams close together and offer little advice about sleep habits. Many students would perform better with fewer hours of study and more hours of sleep.", question:"What is the main argument of this passage?", choices:["Sleep and spaced practice are more important for learning than extra study hours","Students should not study for exams","Sleep helps the brain store memories formed during the day","Schools should give students more time to sleep between exams"], answer:"Sleep and spaced practice are more important for learning than extra study hours", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l3_004", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:5, passage:"Ruby joined the swimming club in autumn. At her first gala she came last in every race. She kept going to practice on cold, dark evenings when her friends stayed home. She learned to breathe on both sides and to push off the wall like a rocket. At the spring gala she did not win — but she beat every time she had ever swum.", question:"What is the main idea of this passage?", choices:["Real progress means beating your own best, not always winning","Ruby came last in every race at her first gala","Swimming clubs practise on cold, dark evenings","Ruby won every race at the spring gala"], answer:"Real progress means beating your own best, not always winning", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l3_005", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:5, passage:"At break time, Leo always played the same chasing game with the same three friends. One rainy day they had to stay inside, and Leo ended up building a marble run with Priya, who he had never really spoken to. It was the best break he could remember. On Monday, the sun came back — and Leo asked Priya to play too.", question:"What is the main message?", choices:["Trying something new can lead to unexpected friendships","Rainy days mean children must stay inside at break","Leo built a marble run with Priya","Chasing games are better with three friends"], answer:"Trying something new can lead to unexpected friendships", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l3_006", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:5, passage:"Every morning, Sam arrived at school early and quietly took the chairs down from the tables before anyone else came in. He never told the teacher it was him. When a new boy asked why he did a job nobody ever saw, Sam shrugged. 'Someone did it for my class last year,' he said. 'I liked how it felt to walk into a ready room.'", question:"Which statement best captures the main idea?", choices:["Quiet kindness can matter even when nobody sees it","Sam took the chairs down before anyone came in","Teachers should thank children who help in class","New pupils ask a lot of questions"], answer:"Quiet kindness can matter even when nobody sees it", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l3_007", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:5, passage:"The history of exploration is full of failures that came before success. Before Edmund Hillary and Tenzing Norgay reached the summit of Everest in 1953, seven major expeditions had failed. Before Roald Amundsen reached the South Pole, Ernest Shackleton turned back just 97 miles short. The Wright Brothers built over a hundred unsuccessful gliders before their first powered flight. Every account of breakthrough achievement contains, if you look closely, a longer account of setback and near-miss. The final success is visible; the years of failure rarely are.", question:"What is the main argument of this passage?", choices:["Visible successes are built on a foundation of unseen failures","Famous explorers often came close to their goal before succeeding","The Wright Brothers failed many times before they could fly","Reaching Everest required many earlier expeditions to fail first"], answer:"Visible successes are built on a foundation of unseen failures", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l3_008", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:5, passage:"Gran's old dog, Bramble, could not fetch any more, and he walked so slowly that trips to the park took all afternoon. 'Why do you keep him?' a neighbour joked. Gran just smiled. Every evening Bramble rested his head on her feet while she read. He knew when she was sad before anyone else did. Some friends do their most important job just by staying close.", question:"What is the main idea of this passage?", choices:["Some friends matter for who they are, not what they can do","Old dogs walk too slowly to go to the park","Gran should get a younger dog that can fetch","Bramble rested his head on Gran's feet every evening"], answer:"Some friends matter for who they are, not what they can do", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l3_009", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:5, passage:"Scientists studying deep ocean trenches have discovered creatures living in extreme conditions that were once thought impossible to support life. Some organisms survive near hydrothermal vents where temperatures reach hundreds of degrees. Others exist in the crushing darkness where no sunlight reaches. Bacteria have been found living in solid rock kilometres underground. These discoveries have expanded our understanding of where life can exist. They have also raised serious questions about whether life might exist in extreme environments on other planets.", question:"What is the main message?", choices:["Life can exist in conditions once thought impossible, raising questions about life elsewhere in the universe","The deep ocean contains creatures adapted to extreme heat and pressure","Scientists have found bacteria living deep underground","Hydrothermal vents support unusual forms of life"], answer:"Life can exist in conditions once thought impossible, raising questions about life elsewhere in the universe", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l3_010", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:5, passage:"Maple Class had two football stars who scored nearly every goal. In the winter tournament, the other team marked them closely, and suddenly nobody could score at all. At half-time the coach changed the plan: pass to everyone, let anyone shoot. The goals that followed came from four different players. Maple Class won — and nobody could say which player had mattered most.", question:"What is the main argument of this passage?", choices:["A team is strongest when everyone gets to play a part","Maple Class had two players who scored nearly every goal","Coaches should change their plan at half-time","The other team played unfairly in the tournament"], answer:"A team is strongest when everyone gets to play a part", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l3_011", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:5, passage:"For the class art show, everyone painted big, bright pictures with lots of glitter. Nia handed in a small drawing of her grandad's hands holding a teacup. Some children laughed and called it plain. On show night, visitors hurried past the glitter — then stopped, crowded round Nia's little drawing, and stayed there the longest. The quietest picture in the room said the most.", question:"What is the main idea?", choices:["Something simple and honest can turn out to be the most powerful","Everyone painted big, bright pictures for the art show","Glitter makes paintings more popular with visitors","Nia drew her grandad's hands holding a teacup"], answer:"Something simple and honest can turn out to be the most powerful", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l3_012", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:5, passage:"Before the nature quiz, Dev told everyone he would win because he knew everything about animals. Amara said she was not sure how she would do — but she had spent the week reading and asking questions anyway. In the quiz, Dev shouted quick answers and got many wrong. Amara took her time, thought carefully, and won. The loudest voice is not always the one that knows the most.", question:"What is the main argument?", choices:["Being sure of yourself is not the same as knowing the answers","Dev shouted his answers quickly in the quiz","Amara won because the questions were easy","Nature quizzes are mostly about animals"], answer:"Being sure of yourself is not the same as knowing the answers", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l3_013", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:5, passage:"In town, Mia could count the stars she saw from her window on one hand. On the school camping trip, far from the streetlights, she looked up and gasped. The sky was crowded with stars, layered and glittering, more than she could ever count. 'They were up there all along,' the teacher said. Mia decided some things are worth travelling into the dark to see.", question:"What is the main idea?", choices:["Getting away from town lights showed Mia a night sky full of wonder","Mia could only see a few stars from her window","School camping trips always happen far from town","The teacher counted every star with Mia"], answer:"Getting away from town lights showed Mia a night sky full of wonder", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l3_014", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:5, passage:"When the school got new climbing frames, Jonah kept saying the old wooden one had been better. 'Everything was more fun back then,' he sighed. Then his friend showed him a photo from two years ago. In it, Jonah stood beside the old frame — with a splinter in his thumb and rain-soaked shoes, frowning. Jonah laughed. Maybe he only remembered the sunny days.", question:"What is the main argument?", choices:["Our memories of the past often leave out the bad parts","The school replaced the old wooden climbing frame","Old climbing frames give children splinters","Jonah's friend keeps photos from two years ago"], answer:"Our memories of the past often leave out the bad parts", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l3_015", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:5, passage:"For five years, the volunteer-run community centre had been the hub of the neighbourhood. It hosted English classes for new arrivals, after-school clubs, a food bank, and a Saturday market. When the council announced it would be closing due to budget cuts, two hundred residents showed up to the public meeting. Within a week, a fundraising campaign had exceeded its target. Businesses donated equipment. Teachers volunteered their time. The centre stayed open. The council said it was the fastest community response they had ever seen.", question:"Which statement best captures the main idea?", choices:["A community's shared ownership of something valuable can mobilise remarkable collective action","Budget cuts threaten vital community services","The community centre provided many important services to local people","Two hundred people attended a public meeting to save the community centre"], answer:"A community's shared ownership of something valuable can mobilise remarkable collective action", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l3_016", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:5, passage:"A rumour raced around the playground: the school pond would be filled in! By lunchtime, everyone had heard a different version, and each teller sounded completely certain. Keisha walked to the office and simply asked. The truth: the pond was being cleaned, not closed. Everyone had heard so much — yet almost nobody had heard anything true. Keisha decided that asking beats guessing.", question:"What is the main argument?", choices:["Hearing lots of talk is not the same as knowing the truth","The school pond was going to be filled in","Keisha walked to the office at lunchtime","Rumours spread around playgrounds very quickly"], answer:"Hearing lots of talk is not the same as knowing the truth", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l3_017", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:5, passage:"Old Omar had kept a notebook since he was fourteen. By the time he was eighty, he had filled sixty-three of them. They contained observations about the weather, overheard conversations, sketches of plants, and thoughts he had at three in the morning. His family could not make much sense of them. After he died, a researcher came to look at the notebooks and found in them a detailed forty-year record of how the marshes near his village had changed — water levels, bird species, plant coverage. It was the kind of long-term data that scientists almost never have. Published in an academic journal, his observations were cited by researchers across the world.", question:"What is the main idea of this passage?", choices:["Careful, patient observation over many years can produce knowledge of extraordinary value","Omar kept detailed notebooks for over sixty years","Scientists rarely have long-term records of how environments change","Omar's notebooks were published in an academic journal after his death"], answer:"Careful, patient observation over many years can produce knowledge of extraordinary value", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l3_018", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:5, passage:"Tom's grandmother knew a special name for every bird on the hill — words from the language she spoke as a girl. Nobody else in the family knew them. One spring, Tom started writing each word in a notebook as she said them, with a little drawing beside it. 'Now they are yours,' Grandma smiled. Tom kept the notebook where he could always find it.", question:"What is the main message?", choices:["Special words can be kept alive by passing them on","Tom's grandmother knew a name for every bird on the hill","Tom enjoyed drawing little pictures of birds","Notebooks should be kept somewhere safe"], answer:"Special words can be kept alive by passing them on", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l3_019", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:5, passage:"The history of science is not a smooth march of progress. It is full of ideas that turned out to be completely wrong. Doctors once believed that bloodletting cured illness. Scientists assumed for centuries that the Earth was at the centre of the universe. Even Einstein resisted the idea that the universe was expanding. Being wrong is not a failure of the scientific method — it is part of how it works. Each wrong idea, if tested carefully, brings scientists closer to the right one. The most dangerous ideas are not the ones that are eventually proven wrong, but the ones that are held too firmly to be tested at all.", question:"What is the main argument?", choices:["Science progresses through being wrong and correcting course, and this is not a flaw but a feature","Famous scientists including Einstein have been wrong about major ideas","Bloodletting and geocentrism were once widely accepted but have since been disproved","Ideas that are never tested are the most dangerous in science"], answer:"Science progresses through being wrong and correcting course, and this is not a flaw but a feature", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },
  { id:"qa_mi_l3_020", grade:"2", skill:"main idea", skillId:"main_idea", difficulty:5, passage:"In Year One, Poppy sang too quietly for the school choir and was told to 'just mouth the words'. After that she only sang alone in her room, where nobody could hear. This year, a new music teacher heard her humming in the corridor and stopped. 'What a lovely voice,' she said. At the summer concert, Poppy sang her first solo — loudly.", question:"What is the main message of this passage?", choices:["Unkind words can make someone hide their talent until encouragement brings it back","Poppy sang alone in her room where nobody could hear","School choirs only want the loudest singers","The music teacher taught Poppy how to sing"], answer:"Unkind words can make someone hide their talent until encouragement brings it back", questionType:"multiple_choice", itemType:"main_idea", itemKey:"main_idea" },

];
